        </div>
        <template v-else>
          <div v-if="studentsWithAvatar.length" class="students-v3__grid">
            <article v-for="item in studentsWithAvatar" :key="item.memberId"><div class="students-v3__avatar"><a v-if="item.outsideUrl" :href="item.outsideUrl" target="_blank" rel="noopener"><img :src="item.avatarUrl" :alt="item.cnName" @error="markAvatarFailed(item.memberId)" /></a><router-link v-else-if="item.insideUrl" :to="item.insideUrl"><img :src="item.avatarUrl" :alt="item.cnName" @error="markAvatarFailed(item.memberId)" /></router-link><img v-else :src="item.avatarUrl" :alt="item.cnName" @error="markAvatarFailed(item.memberId)" /></div><h2><a v-if="item.outsideUrl" :href="item.outsideUrl" target="_blank" rel="noopener">{{ item.cnName }}</a><router-link v-else-if="item.insideUrl" :to="item.insideUrl">{{ item.cnName }}</router-link><template v-else>{{ item.cnName }}</template></h2><p v-if="memberMeta(item)" class="students-v3__meta">{{ memberMeta(item) }}</p><p v-if="memberDetail(item)">{{ memberDetail(item) }}</p><p v-if="activeType === 'phd' && item.graduationDestination" class="students-v3__destination">去向：{{ item.graduationDestination }}</p><a v-if="item.email" class="students-v3__email" :href="'mailto:' + item.email">{{ item.email }}</a></article>
