import { getCoverMembersListAPI } from "@/utils/api/members";
export default { data: () => ({ groups: [], activeType: "phd", keyword: "", loading: true, error: false, failedAvatars: {}, tabs: [{ value: "phd", label: "博士生" }, { value: "master", label: "硕士生" }, { value: "alumni", label: "毕业生" }] }), computed: { activeGroup() { const types = { phd: "phd", master: "graduate_student", alumni: "graduate" }; return this.groups.find((group) => group.ctType === types[this.activeType]); }, students() { const members = this.activeGroup ? this.activeGroup.children || [] : []; const query = this.keyword.toLowerCase(); return query ? members.filter((item) => [item.cnName, item.enName, item.direction, item.cohortYear, item.cohortLabel, item.programType, item.graduationDestination].filter(Boolean).some((value) => String(value).toLowerCase().includes(query))) : members; }, studentsWithAvatar() { return this.students.filter((item) => this.hasStudentAvatar(item)); }, studentsWithoutAvatar() { return this.students.filter((item) => !this.hasStudentAvatar(item)); } }, created() { if (["master", "alumni"].includes(this.$route.query.type)) this.activeType = this.$route.query.type; if (this.$route.query.keyword) this.keyword = String(this.$route.query.keyword); this.load(); }, methods: { async load() { this.loading = true; this.error = false; try { const response = await getCoverMembersListAPI(); if (response && response.code === 200) this.groups = response.data || []; else this.error = true; } catch (error) { this.error = true; } finally { this.loading = false; } }, selectType(type) { this.activeType = type; const navigation = this.$router.replace({ path: "/ryjs/students", query: { type } }); if (navigation && navigation.catch) navigation.catch(() => {}); }, hasStudentAvatar(item) { return Boolean(item.avatarUrl) && !this.failedAvatars[item.memberId]; }, markAvatarFailed(memberId) { this.$set(this.failedAvatars, memberId, true); }, memberMeta(item) { const grade = item.cohortYear ? `${item.cohortYear}级` : ""; if (this.activeType === "alumni") { const degree = item.degreeType === "bachelor" ? "本科" : item.degreeType === "phd" ? "博士" : "硕士"; return grade ? `${grade} · ${degree}` : degree; } return item.programType ? `${grade} · ${item.programType}` : grade; }, memberDetail(item) { return item.direction ? `研究方向：${item.direction}` : ""; } } };
</script>

